using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

// Web defaults include the default reflection-based resolver,
// so GetTypeInfo<T> will succeed for any serialisable type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<WeatherForecast> typedInfo = webOptions.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> returned type: {typedInfo.Type.Name}");

// Use the typed metadata to serialise directly
var forecast = new WeatherForecast("Sunny", 27);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialised: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// Options with a source-gen context that only knows about WeatherForecast.
var strictOptions = new JsonSerializerOptions
{
    TypeInfoResolver = MyContext.Default
};

// This type IS in the context → should succeed
if (strictOptions.TryGetTypeInfo<WeatherForecast>(out var foundInfo))
    Console.WriteLine($"TryGet for WeatherForecast succeeded – type: {foundInfo!.Type.Name}");
else
    Console.WriteLine("TryGet for WeatherForecast: not available");

// This type is NOT in the context → should return false, no exception
if (strictOptions.TryGetTypeInfo<UnknownType>(out var missingInfo))
    Console.WriteLine($"TryGet for UnknownType succeeded – type: {missingInfo!.Type.Name}");
else
    Console.WriteLine("TryGet for UnknownType: not available (no exception thrown)");

// --- Types ---

public record WeatherForecast(string Summary, int TemperatureC);
public record UnknownType(int Id);

// Source-gen context that only includes WeatherForecast
[JsonSerializable(typeof(WeatherForecast))]
internal partial class MyContext : JsonSerializerContext;

